return function(import)
    local Players = game:GetService(S(193))
    local createWindow = import(S(29))(import)
    local i18n = import(S(312))
    local antiAfk = import(S(304))(import)
    local interactionLogger = import(S(103))(import)
    local scheduler = import(S(102))(import)
    local config = import(S(497))(import)
    local log = import(S(356))
    local window = createWindow({
        Subtitle = S(484),
    })
    local function persistentToggle(card, key, apply)
        local saved = config.Get(key, false)
        card:AddToggle(saved, function(state)
            config.Set(key, state)
            apply(state)
        end)
        if saved then
            apply(true)
        end
    end
    local getCurrentPlot = import(S(133))
    local getPlotParts = import(S(384))
    local dumpInstance = import(S(467))
    local dumpRemotes = import(S(406))(import)
    local dumpSellCards = import(S(144))(import)
    local dumpGui = import(S(266))(import)
    local dumpChest = import(S(153))(import)
    local autoMine = import(S(2))(import)
    local autoPlace = import(S(80))(import)
    local autoChest = import(S(352))(import)
    local autoSell = import(S(267))(import)
    local autoUpgrade = import(S(84))(import)
    scheduler.RegisterStandalone(S(242), autoMine.Step, autoMine.IsEnabled)
    scheduler.RegisterStandalone(S(255), autoUpgrade.Step, autoUpgrade.IsEnabled)
    scheduler.RegisterExclusive(S(279), autoPlace.Step, autoPlace.IsEnabled, autoPlace.IsBusy)
    scheduler.RegisterExclusive(S(254), autoChest.Step, autoChest.IsEnabled, autoChest.IsBusy)
    scheduler.RegisterExclusive(S(505), autoSell.Step, autoSell.IsEnabled, autoSell.IsBusy)
    scheduler.Start()
    local farmTab = window:AddTab(S(358), S(450))
    persistentToggle(farmTab:AddCard(
        S(20),
        S(531)
    ), S(374), autoMine.SetEnabled)
    persistentToggle(farmTab:AddCard(
        S(197),
        S(506)
    ), S(156), autoPlace.SetEnabled)
    persistentToggle(farmTab:AddCard(
        S(262),
        S(141)
    ), S(221), autoChest.SetEnabled)
    persistentToggle(farmTab:AddCard(
        S(341),
        S(213)
    ), S(397), autoSell.SetEnabled)
    persistentToggle(farmTab:AddCard(
        S(367),
        S(435)
    ), S(158), autoUpgrade.SetEnabled)
    local debugCard = farmTab:AddCard(S(381), S(303))
    local checkBtn
    checkBtn = debugCard:AddButton(S(490), function()
        local plot = getCurrentPlot()
        if not plot then
            checkBtn.Text = S(415)
            log(S(508))
            return
        end
        local parts = getPlotParts(plot)
        local nodeCount = parts.Nodes and #parts.Nodes:GetChildren() or 0
        local holderCount = parts.Holders and #parts.Holders:GetChildren() or 0
        checkBtn.Text = plot.Name
        log(string.format(
            S(59),
            plot.Name, nodeCount, holderCount
        ))
    end)
    local dumpCard = farmTab:AddCard(
        S(371),
        S(488)
    )
    local dumpBtn
    dumpBtn = dumpCard:AddButton(S(288), function()
        local plot = getCurrentPlot()
        if not plot then
            dumpBtn.Text = S(324)
            return
        end
        local ok, err = log(S(347))
        if not ok then
            dumpBtn.Text = S(18)
            dumpCard:SetSubtitle(S(393) .. tostring(err))
            return
        end
        local parts = getPlotParts(plot)
        local firstNode = parts.Nodes and parts.Nodes:GetChildren()[1]
        if firstNode then
            log(S(247) .. firstNode.Name .. S(509))
            dumpInstance(firstNode, log)
        else
            log(S(178))
        end
        local firstHolder = parts.Holders and parts.Holders:GetChildren()[1]
        if firstHolder then
            log(S(171) .. firstHolder.Name .. S(440))
            dumpInstance(firstHolder, log)
        else
            log(S(192))
        end
        dumpBtn.Text = S(380)
    end)
    local toolDumpCard = farmTab:AddCard(
        S(101),
        S(465)
    )
    local toolDumpBtn
    toolDumpBtn = toolDumpCard:AddButton(S(389), function()
        local backpack = Players.LocalPlayer:FindFirstChild(S(369))
        local tool = backpack and backpack:FindFirstChildWhichIsA(S(466))
        if not tool then
            toolDumpBtn.Text = S(517)
            return
        end
        log(S(503) .. tool.Name .. S(544))
        for attrName, attrValue in pairs(tool:GetAttributes()) do
            log(S(373) .. attrName .. S(142) .. tostring(attrValue))
        end
        dumpInstance(tool, log)
        toolDumpBtn.Text = S(291)
    end)
    local remoteDumpCard = farmTab:AddCard(
        S(402),
        S(15)
    )
    local remoteDumpBtn
    remoteDumpBtn = remoteDumpCard:AddButton(S(329), function()
        local count = dumpRemotes()
        remoteDumpBtn.Text = count .. S(434)
    end)
    local sellCardsDumpCard = farmTab:AddCard(
        S(241),
        S(194)
    )
    local sellCardsDumpBtn
    sellCardsDumpBtn = sellCardsDumpCard:AddButton(S(526), function()
        local count = dumpSellCards()
        sellCardsDumpBtn.Text = count .. S(282)
    end)
    local guiDumpCard = farmTab:AddCard(
        S(152),
        S(272)
    )
    local guiDumpBtn
    guiDumpBtn = guiDumpCard:AddButton(S(122), function()
        dumpGui()
        guiDumpBtn.Text = S(273)
    end)
    local chestDumpCard = farmTab:AddCard(
        S(502),
        S(231)
    )
    local chestDumpBtn
    chestDumpBtn = chestDumpCard:AddButton(S(99), function()
        local count = dumpChest()
        chestDumpBtn.Text = count .. S(183)
    end)
    local settingsTab = window:AddTab(S(431), S(209))
    persistentToggle(
        settingsTab:AddCard(S(498), S(478)),
        S(338),
        antiAfk.SetEnabled
    )
    persistentToggle(
        settingsTab:AddCard(
            S(455),
            S(340)
        ),
        S(518),
        interactionLogger.SetEnabled
    )
    local savedScale = config.Get(S(460), 100)
    settingsTab:AddSlider(S(245), S(224), 50, 150, savedScale, function(value)
        config.Set(S(492), value)
        window:SetScale(value)
    end)
    window:SetScale(savedScale)
    local savedLanguage = config.Get(S(44), 1)
    settingsTab:AddSegmented({ S(469), S(215), S(536) }, savedLanguage, function(index, value)
        local code = ({ S(204), S(320), S(240) })[index]
        config.Set(S(37), index)
        i18n.SetLanguage(code)
    end)
    i18n.SetLanguage(({ S(112), S(308), S(437) })[savedLanguage] or S(82))
    log(S(521) .. config.Path())
    window:OnDestroy(function()
        scheduler.Stop()
        autoMine.SetEnabled(false)
        autoPlace.SetEnabled(false)
        autoChest.SetEnabled(false)
        antiAfk.SetEnabled(false)
        interactionLogger.SetEnabled(false)
        autoSell.SetEnabled(false)
        autoUpgrade.SetEnabled(false)
    end)
end
end
modules[S(433)] = function()
return {
    [79389059854988] = S(516),
}
end
import(S(234))(import)
